   6│ /// Minimal length-prefixed Unix-domain-socket transport shared by the `kist` client and the `kist-control`
   7│ /// broker. Framing is `KistControlFraming` (4-byte big-endian length + JSON). Blocking I/O, one request per
   8│ /// connection (the broker's actions are discrete + serialized). The socket path lives in a 0700 per-user dir.
   9│ public enum UnixSocketTransport {
  10│ 
  11│     /// Canonical broker socket path: `~/Library/Application Support/kist/control.sock` (dir 0700, socket 0600).
  12│     public static func defaultSocketPath() -> String {
  13│         let base = (NSHomeDirectory() as NSString)
  14│             .appendingPathComponent("Library/Application Support/kist")
  15│         return (base as NSString).appendingPathComponent("control.sock")
  16│     }
  17│ 
  18│     public enum TransportError: Error, Equatable {
  19│         case socketCreateFailed(Int32), bindFailed(Int32), connectFailed(Int32), pathTooLong
  20│         case peerClosed, ioFailed(Int32), badFrame
  21│     }
  22│ 
  23│     // MARK: - low-level framed read/write over an fd
  24│ 
  25│     public static func writeFrame<T: Encodable>(_ value: T, to fd: Int32) throws {
  26│         let data = try KistControlFraming.encode(value)
  27│         try data.withUnsafeBytes { raw in
  28│             var off = 0
  29│             while off < data.count {
  30│                 let n = write(fd, raw.baseAddress!.advanced(by: off), data.count - off)
  31│                 if n <= 0 { throw TransportError.ioFailed(errno) }
  32│                 off += n
  33│             }
  34│         }
  35│     }
  36│ 
  37│     public static func readFrame<T: Decodable>(_ type: T.Type, from fd: Int32, maxBytes: Int = 64 * 1024 * 1024) throws -> T {
  38│         var buffer = Data()
  39│         var chunk = [UInt8](repeating: 0, count: 8192)
  40│         while true {
  41│             if let (value, _) = try KistControlFraming.decode(T.self, from: buffer, maxBytes: maxBytes) {
  42│                 return value
  43│             }
  44│             let n = chunk.withUnsafeMutableBytes { read(fd, $0.baseAddress, $0.count) }
  45│             if n == 0 { throw TransportError.peerClosed }
  46│             if n < 0 { throw TransportError.ioFailed(errno) }
  47│             buffer.append(contentsOf: chunk[0..<n])
  48│         }
  49│     }
