  51│     public static func makeSockaddr(path: String) throws -> sockaddr_un {
  52│         var addr = sockaddr_un()
  53│         addr.sun_family = sa_family_t(AF_UNIX)
  54│         let maxLen = MemoryLayout.size(ofValue: addr.sun_path)
  55│         let bytes = Array(path.utf8)
  56│         guard bytes.count < maxLen else { throw TransportError.pathTooLong }
  57│         withUnsafeMutableBytes(of: &addr.sun_path) { raw in
  58│             for (i, b) in bytes.enumerated() { raw[i] = b }
  59│             raw[bytes.count] = 0
  60│         }
  61│         return addr
  62│     }
