  66│     /// Connect, send one request, read one response, close.
  67│     public static func request(_ req: DesktopActionRequest, socketPath: String) throws -> DesktopActionResponse {
  68│         let fd = socket(AF_UNIX, sockStreamType, 0)
  69│         if fd < 0 { throw TransportError.socketCreateFailed(errno) }
  70│         defer { close(fd) }
  71│         var addr = try makeSockaddr(path: socketPath)
  72│         let rc = withUnsafePointer(to: &addr) { p in
  73│             p.withMemoryRebound(to: sockaddr.self, capacity: 1) { connect(fd, $0, socklen_t(MemoryLayout<sockaddr_un>.size)) }
  74│         }
  75│         if rc != 0 { throw TransportError.connectFailed(errno) }
  76│         try writeFrame(req, to: fd)
  77│         return try readFrame(DesktopActionResponse.self, from: fd)
  78│     }
