  91│ /// Length-prefixed framing for a stream transport (Unix-domain socket): a 4-byte big-endian UInt32 length
  92│ /// followed by that many JSON bytes. Pure + testable; the socket layer just does read/write of these frames.
  93│ public enum KistControlFraming {
  94│     public static func encode<T: Encodable>(_ value: T) throws -> Data {
  95│         let body = try JSONEncoder().encode(value)
  96│         var length = UInt32(body.count).bigEndian
  97│         var out = Data(bytes: &length, count: 4)
  98│         out.append(body)
  99│         return out
 100│     }
 101│ 
 102│     /// Decode one frame from `buffer`. Returns the value + bytes consumed, or nil if a full frame isn't buffered
 103│     /// yet. Throws on a corrupt/oversized frame (fail-closed).
 104│     public static func decode<T: Decodable>(_ type: T.Type, from buffer: Data,
 105│                                             maxBytes: Int = 64 * 1024 * 1024) throws -> (value: T, consumed: Int)? {
 106│         guard buffer.count >= 4 else { return nil }
 107│         let len = buffer.prefix(4).reduce(UInt32(0)) { ($0 << 8) | UInt32($1) }
 108│         if Int(len) > maxBytes { throw KistControlFramingError.frameTooLarge(Int(len)) }
 109│         let total = 4 + Int(len)
 110│         guard buffer.count >= total else { return nil }
 111│         let body = buffer.subdata(in: (buffer.startIndex + 4)..<(buffer.startIndex + total))
 112│         let value = try JSONDecoder().decode(T.self, from: body)
 113│         return (value, total)
 114│     }
 115│ }
